		const position = selections[i].getPosition();
		const deleteSelection = new Range(
			position.lineNumber,
			position.column - 1,
			position.lineNumber,
			position.column + 1
		);
		commands[i] = new ReplaceCommand(deleteSelection, '');
	}
	return [true, commands];

